persistence.schema_sql:
CREATE TABLE IF NOT EXISTS meta(key TEXT PRIMARY KEY, value TEXT NOT NULL) STRICT;
CREATE TABLE IF NOT EXISTS current_projection(singleton INTEGER PRIMARY KEY CHECK(singleton = 1), version INTEGER NOT NULL, status TEXT NOT NULL, active_selector TEXT, active_package_hash TEXT, previous_selector TEXT, previous_package_hash TEXT, failure_code TEXT, projection_hash TEXT NOT NULL) STRICT;
CREATE TABLE IF NOT EXISTS operations(operation_id TEXT PRIMARY KEY, owner_epoch TEXT NOT NULL, method TEXT NOT NULL, selector TEXT, prepared_id TEXT, status TEXT NOT NULL, phase TEXT NOT NULL, intent_json TEXT NOT NULL, result_json TEXT, started_at TEXT NOT NULL, resolved_at TEXT) STRICT;
CREATE UNIQUE INDEX IF NOT EXISTS one_global_pending ON operations(status) WHERE resolved_at IS NULL;
CREATE TABLE IF NOT EXISTS effects(effect_id TEXT PRIMARY KEY, operation_id TEXT NOT NULL REFERENCES operations(operation_id), owner_epoch TEXT NOT NULL, ordinal INTEGER NOT NULL, kind TEXT NOT NULL, phase TEXT NOT NULL, intent_json TEXT NOT NULL, resolution_json TEXT, diagnostic_hash TEXT, created_at TEXT NOT NULL, resolved_at TEXT, UNIQUE(operation_id, ordinal)) STRICT;
CREATE TABLE IF NOT EXISTS events(sequence INTEGER PRIMARY KEY AUTOINCREMENT, operation_id TEXT NOT NULL REFERENCES operations(operation_id), owner_epoch TEXT NOT NULL, kind TEXT NOT NULL, status TEXT NOT NULL, data_json TEXT NOT NULL, created_at TEXT NOT NULL) STRICT;
CREATE TABLE IF NOT EXISTS diagnostic_blobs(blob_hash TEXT PRIMARY KEY, byte_size INTEGER NOT NULL CHECK(byte_size >= 0), data BLOB, created_at TEXT NOT NULL, purged_at TEXT) STRICT;
CREATE TABLE IF NOT EXISTS packages(package_hash TEXT PRIMARY KEY, plugin_name TEXT, plugin_version TEXT, manifest_hash TEXT, has_hooks INTEGER NOT NULL CHECK(has_hooks IN (0, 1)), hook_subject_hash TEXT, entry_count INTEGER NOT NULL CHECK(entry_count >= 0), file_count INTEGER NOT NULL CHECK(file_count >= 0), byte_size INTEGER NOT NULL CHECK(byte_size >= 0), inventory_bytes INTEGER NOT NULL CHECK(inventory_bytes >= 0), inventory_json TEXT NOT NULL, preserved_root TEXT NOT NULL, created_at TEXT NOT NULL, disposed_at TEXT) STRICT;
CREATE TABLE IF NOT EXISTS snapshots(snapshot_hash TEXT PRIMARY KEY, entry_count INTEGER NOT NULL CHECK(entry_count >= 0), file_count INTEGER NOT NULL CHECK(file_count >= 0), byte_size INTEGER NOT NULL CHECK(byte_size >= 0), inventory_bytes INTEGER NOT NULL CHECK(inventory_bytes >= 0), inventory_json TEXT NOT NULL, preserved_root TEXT NOT NULL, created_at TEXT NOT NULL, disposed_at TEXT) STRICT;
CREATE TABLE IF NOT EXISTS marketplaces(marketplace_id TEXT PRIMARY KEY, registration_name TEXT NOT NULL, root TEXT NOT NULL UNIQUE, selector TEXT NOT NULL, package_hash TEXT NOT NULL REFERENCES packages(package_hash), purpose TEXT NOT NULL, registered INTEGER NOT NULL CHECK(registered IN (0, 1)), created_at TEXT NOT NULL, disposed_at TEXT) STRICT;
CREATE TABLE IF NOT EXISTS preparations(prepared_id TEXT PRIMARY KEY, selector TEXT NOT NULL, activation_selector TEXT NOT NULL, rollback_selector TEXT NOT NULL, status TEXT NOT NULL, candidate_package_hash TEXT NOT NULL REFERENCES packages(package_hash), previous_selector TEXT NOT NULL, previous_package_hash TEXT NOT NULL REFERENCES packages(package_hash), previous_root TEXT NOT NULL, candidate_marketplace_id TEXT NOT NULL REFERENCES marketplaces(marketplace_id), rollback_marketplace_id TEXT NOT NULL REFERENCES marketplaces(marketplace_id), plugin_data_snapshot_hash TEXT REFERENCES snapshots(snapshot_hash), plugin_data_snapshot_operation_id TEXT REFERENCES operations(operation_id), migration_plan_json TEXT, trust_nonce TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, cancelled_at TEXT, finalized_at TEXT) STRICT;
CREATE TABLE IF NOT EXISTS operation_leases(operation_id TEXT PRIMARY KEY REFERENCES operations(operation_id), lease_id TEXT NOT NULL, lease_json TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('HELD', 'RELEASED')), acquired_effect_id TEXT NOT NULL REFERENCES effects(effect_id), updated_at TEXT NOT NULL) STRICT;
CREATE TABLE IF NOT EXISTS operation_snapshots(operation_id TEXT PRIMARY KEY REFERENCES operations(operation_id), snapshot_hash TEXT NOT NULL REFERENCES snapshots(snapshot_hash), capability_id TEXT NOT NULL, external_snapshot_id TEXT NOT NULL, capture_receipt_hash TEXT NOT NULL, restore_receipt_hash TEXT, status TEXT NOT NULL CHECK(status IN ('CAPTURED', 'RESTORED', 'DISPOSED')), updated_at TEXT NOT NULL) STRICT;
CREATE TABLE IF NOT EXISTS recoveries(operation_id TEXT PRIMARY KEY REFERENCES operations(operation_id), backup_root TEXT, snapshot_hash TEXT NOT NULL REFERENCES snapshots(snapshot_hash), restore_receipt_hash TEXT, created_at TEXT NOT NULL, disposed_at TEXT) STRICT;
